    if (!(vert ? vseg(bx, by) : hseg(bx, by))) continue;
    const along = (vert ? by : bx) * 8 + 2.5 + Math.random() * 4.5, lane = (vert ? bx : by) * 8 + 1 + (vert ? 0.4 : -0.4) * dir;
