  const c0 = Math.max(0, Math.floor(cx - hw * sc)), c1 = Math.min(cols, Math.ceil(cx + hw * sc));
  const r0 = Math.max(0, Math.floor(hor - (z0 + h - eye) / dz)), r1 = Math.min(rows, Math.ceil(hor - (z0 - eye) / dz));
